import React, { useState } from "react";

function Dashboard() {
  const [amount, setAmount] = useState(100000);
  const [years, setYears] = useState(1);

  const daily = (amount / (365 * years)).toFixed(2);
  const weekly = (amount / (52 * years)).toFixed(2);
  const monthly = (amount / (12 * years)).toFixed(2);
  const yearly = (amount / years).toFixed(2);

  return (
    <div className="p-10">
      <h1 className="text-3xl font-bold text-purple-400 mb-6">
        Goals Dashboard
      </h1>

      <div className="bg-gray-800 p-6 rounded-xl mb-6">
        <input
          type="number"
          placeholder="Target Amount"
          className="p-2 mr-4 rounded bg-gray-700 border border-gray-600"
          onChange={(e) => setAmount(e.target.value)}
        />

        <input
          type="number"
          placeholder="Years"
          className="p-2 rounded bg-gray-700 border border-gray-600"
          onChange={(e) => setYears(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-2 gap-6">
        <div className="bg-gray-800 p-4 rounded-xl">Daily: ₹{daily}</div>
        <div className="bg-gray-800 p-4 rounded-xl">Weekly: ₹{weekly}</div>
        <div className="bg-gray-800 p-4 rounded-xl">Monthly: ₹{monthly}</div>
        <div className="bg-gray-800 p-4 rounded-xl">Yearly: ₹{yearly}</div>
      </div>
    </div>
  );
}

export default Dashboard;
